def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    if not jobs:
        return 0

    times = sorted({t for start, end, _ in jobs for t in (start, end)})
    index = {t: i for i, t in enumerate(times)}
    n = len(times)
    graph = [[] for _ in range(n)]

    def add_edge(u: int, v: int, capacity: int, cost: int) -> None:
        graph[u].append([v, capacity, cost, len(graph[v])])
        graph[v].append([u, 0, -cost, len(graph[u]) - 1])

    for i in range(n - 1):
        add_edge(i, i + 1, k, 0)

    for start, end, pay in jobs:
        add_edge(index[start], index[end], 1, -pay)

    # Initial shortest-path potentials are computed on the forward DAG.
    inf = float("inf")
    potential = [inf] * n
    potential[0] = 0
    for u in range(n):
        for v, capacity, cost, _ in graph[u]:
            if capacity and v > u:
                potential[v] = min(potential[v], potential[u] + cost)

    import heapq

    total_cost = 0
    for _ in range(k):
        dist = [inf] * n
        parent = [None] * n
        dist[0] = 0
        heap = [(0, 0)]

        while heap:
            distance, u = heapq.heappop(heap)
            if distance != dist[u]:
                continue
            for edge_index, (v, capacity, cost, _) in enumerate(graph[u]):
                if capacity:
                    new_distance = distance + cost + potential[u] - potential[v]
                    if new_distance < dist[v]:
                        dist[v] = new_distance
                        parent[v] = (u, edge_index)
                        heapq.heappush(heap, (new_distance, v))

        for v in range(n):
            if dist[v] < inf:
                potential[v] += dist[v]

        v = n - 1
        while v:
            u, edge_index = parent[v]
            edge = graph[u][edge_index]
            total_cost += edge[2]
            edge[1] -= 1
            graph[v][edge[3]][1] += 1
            v = u

    return -total_cost
